Correct the single semantic bug and return a complete replacement source file.

```python
from copy import deepcopy


class MemoTable:
    def __init__(self):
        self._values = {}

    def get_or_compute(self, key, producer):
        if not callable(producer):
            raise TypeError("producer must be callable")
        try:
            hash(key)
        except TypeError:
            raise TypeError("key must be hashable") from None
        cached = self._values.get(key)
        if cached:
            return deepcopy(cached)
        value = producer()
        self._values[key] = deepcopy(value)
        return deepcopy(value)

    def clear(self):
        self._values.clear()
